QUESTIONS.push(
{"id": "TBL3-001", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "concept": "tbl-apap-symptoms", "tags": ["smith", "key"], "source": "both", "stem": "Which entry gives the symptoms and diagnostic method for acute acetaminophen poisoning?", "options": [{"t": "Nausea/vomiting and signs of liver failure; blood levels can be measured", "correct": true, "why": "The acetaminophen row: nausea/vomiting, clinical signs of liver failure, and acetaminophen levels can be measured in the blood."}, {"t": "Anion-gap metabolic acidosis and ocular toxicity", "correct": false, "why": "That is methanol, in the toxic alcohols row."}, {"t": "Hyperventilation and respiratory alkalosis, then metabolic acidosis and hyperthermia", "correct": false, "why": "That is the salicylates row."}, {"t": "Central nervous system (CNS) depression with relatively normal vital signs", "correct": false, "why": "That is the benzodiazepines row."}, {"t": "Hypoglycemia", "correct": false, "why": "That is the sulfonylureas and meglitinides row."}], "teach": "The acetaminophen row lists nausea/vomiting and clinical signs of liver failure, and acetaminophen levels can be measured in the blood. Acetaminophen was the first compound the room named on 10/19 when she asked which compounds emergency rooms test the blood for.", "quote": "Acetaminophen, OK, acetaminophen. Salicylates Iron Beta blockers, calcium channel blockers, and there's a few others", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’; transcript 10/19"},
{"id": "TBL3-002", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-apap-antidote", "tags": ["smith", "key"], "source": "both", "stem": "What is the antidote for acetaminophen overdose?", "options": [{"t": "N-acetylcysteine", "correct": true, "why": "The acetaminophen row: N-acetylcysteine."}, {"t": "Fomepizole", "correct": false, "why": "Fomepizole (or ethanol) is the toxic alcohols antidote."}, {"t": "Deferoxamine", "correct": false, "why": "Deferoxamine is the iron antidote."}, {"t": "Octreotide", "correct": false, "why": "Octreotide is the sulfonylurea and meglitinide antidote."}, {"t": "Digoxin specific antibody fragments", "correct": false, "why": "That is the digoxin antidote."}], "teach": "N-acetylcysteine (NAC) is the acetaminophen antidote. On 10/19 she placed it under enhancing metabolism: NAC is given as a drug and supplies ingredients to make more glutathione, which conjugates the toxic metabolite NAPQI.", "quote": "anastylcysteine, we give it as a drug. And it's giving ingredients to the system to create more glutathione.", "note": "The transcript renders N-acetylcysteine as \"anastylcysteine\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’; transcript 10/19"},
{"id": "TBL3-003", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-apap-moa", "tags": ["smith", "key"], "source": "both", "stem": "What is the mechanism of action of N-acetylcysteine (NAC) in acetaminophen overdose?", "options": [{"t": "Replenishes glutathione", "correct": true, "why": "The key's mechanism column: replenishes glutathione. On 10/19 she said NAC supplies ingredients to make more glutathione."}, {"t": "Induces the enzymes that metabolize acetaminophen", "correct": false, "why": "On 10/19 she said enzyme induction cannot be done fast enough in a poisoning; her key: replenishes glutathione."}, {"t": "Inhibition of alcohol dehydrogenase", "correct": false, "why": "That is ethanol or fomepizole, for the toxic alcohols."}, {"t": "Chelates the circulating ferric iron", "correct": false, "why": "That is deferoxamine, for iron."}, {"t": "Renal ion trapping to enhance elimination", "correct": false, "why": "That is sodium bicarbonate, for salicylates."}], "teach": "Her key: N-acetylcysteine replenishes glutathione. Glutathione conjugates NAPQI, the toxic metabolite of acetaminophen; in overdose the glutathione runs short, and NAC provides ingredients to make more. On 10/19 she classed this as enhancing metabolism by giving a cofactor.", "quote": "anastylcysteine, we give it as a drug. And it's giving ingredients to the system to create more glutathione.", "note": "Same fact as L16-019 (the acetaminophen scheme), here in the key's wording.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’; transcript 10/19", "dupOf": "L16-019"},
{"id": "TBL3-004", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "apply", "concept": "tbl-apap-8h", "tags": ["smith", "key"], "source": "slide", "stem": "At what time after an acetaminophen overdose does the antidote lose effectiveness?", "options": [{"t": "About 8 hours after overdose", "correct": true, "why": "Her key: about 8 hours after overdose."}, {"t": "About 2 hours after overdose", "correct": false, "why": "Up to about 2 hours is the single-dose activated charcoal window from 10/19, not the N-acetylcysteine time point."}, {"t": "About 48 hours after overdose", "correct": false, "why": "Her key gives about 8 hours."}, {"t": "About 24 hours after overdose", "correct": false, "why": "Her key gives about 8 hours."}, {"t": "About 72 hours after overdose", "correct": false, "why": "Her key gives about 8 hours."}], "teach": "The special-considerations question for acetaminophen asks when the antidote loses effectiveness. Her key: about 8 hours after overdose. The second half of the question asks whether to give it after that point, and the answer is yes.", "note": "The 8-hour point is in her key only; it was not stated aloud on 10/19 or 10/20. Keyed on her key, which she said sets the detail expected.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’"},
{"id": "TBL3-005", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "apply", "concept": "tbl-apap-still-give", "tags": ["smith", "key"], "source": "slide", "stem": "A patient arrives 12 hours after an acetaminophen overdose, past the time point when N-acetylcysteine loses effectiveness. Should it still be given?", "options": [{"t": "Yes", "correct": true, "why": "Her key: should you still give it past that time point? Yes."}, {"t": "No; past that point it no longer works", "correct": false, "why": "Her key says it loses effectiveness, not all effect, and answers yes: still give it."}, {"t": "Only if the blood level is still rising", "correct": false, "why": "Her key places no condition on it: yes."}, {"t": "Only if signs of liver failure have appeared", "correct": false, "why": "Her key places no condition on it: yes."}], "teach": "The acetaminophen special-considerations question has two parts. The antidote loses effectiveness about 8 hours after overdose, and it should still be given past that time point. Losing effectiveness is not the same as having no effect.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’"},
{"id": "TBL3-006", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "concept": "tbl-methanol-symptoms", "tags": ["smith", "key"], "source": "both", "stem": "Which findings do the active metabolites of methanol cause?", "options": [{"t": "Anion-gap metabolic acidosis and ocular toxicity", "correct": true, "why": "The toxic alcohols row: methanol active metabolites can cause anion-gap metabolic acidosis and ocular toxicity. On 10/19 she named formic acid, which damages the retina."}, {"t": "Crystals in the microvasculature; renal toxicity", "correct": false, "why": "That is ethylene glycol, the other toxic alcohol."}, {"t": "Elevated serum potassium and arrhythmias", "correct": false, "why": "That is digoxin."}, {"t": "Hypoglycemia", "correct": false, "why": "That is sulfonylureas and meglitinides."}, {"t": "Respiratory alkalosis, then metabolic acidosis with hyperthermia and seizures", "correct": false, "why": "That is salicylates."}], "teach": "Methanol is not the problem itself; its active metabolites are. Her key lists anion-gap metabolic acidosis and ocular toxicity. On 10/19 she named formic acid as the toxic metabolite that damages the retina and causes loss of sight.", "quote": "Formic acid will cause damage, especially to the eyes, to the retina of the eyes.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Toxic alcohols’; transcript 10/19"},
{"id": "TBL3-007", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "concept": "tbl-eg-symptoms", "tags": ["smith", "key"], "source": "both", "stem": "Which finding do the active metabolites of ethylene glycol cause?", "options": [{"t": "Crystals in the microvasculature; renal toxicity is common", "correct": true, "why": "The toxic alcohols row: ethylene glycol active metabolites can crystallize in the microvasculature; renal toxicity is common."}, {"t": "Ocular toxicity leading to loss of sight", "correct": false, "why": "That is methanol."}, {"t": "Liver failure after nausea and vomiting", "correct": false, "why": "That is acetaminophen."}, {"t": "Somnolence, coma and decreased pupils", "correct": false, "why": "That is opioids."}, {"t": "Altered mental status with hypotension, bradycardia and respiratory depression", "correct": false, "why": "That is beta blockers."}], "teach": "Her key: ethylene glycol active metabolites can crystallize in the microvasculature, and renal toxicity is common. On 10/19 she named the metabolite oxalic acid, which forms microcrystals that block blood flow in small vessels and damage organs.", "quote": "sometimes the oxalic acid can form into little crystals and blocks blood flow and damages those organs.", "note": "The key spells it \"crystalize\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Toxic alcohols’; transcript 10/19"},
{"id": "TBL3-008", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-alc-antidote", "tags": ["smith", "key"], "source": "both", "stem": "What are the antidotes for toxic alcohol (methanol or ethylene glycol) poisoning?", "options": [{"t": "Ethanol or fomepizole", "correct": true, "why": "The toxic alcohols row: ethanol or fomepizole."}, {"t": "N-acetylcysteine", "correct": false, "why": "That is the acetaminophen antidote."}, {"t": "Naloxone", "correct": false, "why": "That is the opioid antidote."}, {"t": "Octreotide", "correct": false, "why": "That is the sulfonylurea and meglitinide antidote."}, {"t": "Supportive care and intravenous sodium bicarbonate", "correct": false, "why": "That is the salicylates row."}], "teach": "There are two possible treatments for methanol and ethylene glycol: ethanol or fomepizole. Both work on the enzyme that makes the toxic metabolites. Ethylene glycol and methanol share the antidote.", "quote": "So, you can give ethanol. And outcompete the alcohol alcohol dehydrogenase metabolism of methanol or ethylene glycol. Same thing with fomeprazole. It'll, it'll bind to and inhibit the alcohol dehydrogenase and prevent the metabolism of methanol or ethylene glycol.", "note": "The transcript renders fomepizole as \"fomeprazole\" and \"omeprazole\"; omeprazole is a proton pump inhibitor, so this is a transcription error (see L16-008).", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Toxic alcohols’; transcript 10/19"},
{"id": "TBL3-009", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-alc-moa", "tags": ["smith", "key"], "source": "both", "stem": "What is the mechanism of action of ethanol and fomepizole in toxic alcohol poisoning?", "options": [{"t": "Inhibition of alcohol dehydrogenase", "correct": true, "why": "The key's mechanism column: inhibition of alcohol dehydrogenase."}, {"t": "Replenishes glutathione", "correct": false, "why": "That is N-acetylcysteine."}, {"t": "Renal ion trapping to enhance elimination", "correct": false, "why": "That is sodium bicarbonate for salicylates."}, {"t": "Competitive antagonist of opioid receptors", "correct": false, "why": "That is naloxone."}, {"t": "Chelates the circulating ferric iron", "correct": false, "why": "That is deferoxamine."}], "teach": "Ethanol and fomepizole both inhibit alcohol dehydrogenase, the enzyme that starts the conversion of methanol and ethylene glycol to their toxic metabolites. On 10/19 she said ethanol outcompetes the enzyme and fomepizole binds to and inhibits it. This is the inhibit-bioactivation treatment.", "quote": "So, you can give ethanol. And outcompete the alcohol alcohol dehydrogenase metabolism of methanol or ethylene glycol. Same thing with fomeprazole. It'll, it'll bind to and inhibit the alcohol dehydrogenase and prevent the metabolism of methanol or ethylene glycol.", "note": "The transcript renders fomepizole as \"fomeprazole\" and \"omeprazole\"; omeprazole is a proton pump inhibitor, so this is a transcription error (see L16-008).", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Toxic alcohols’; transcript 10/19", "dupOf": "L16-008"},
{"id": "TBL3-010", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "apply", "concept": "tbl-alc-advantage", "tags": ["smith", "key"], "source": "both", "stem": "There are two possible treatments for toxic alcohol poisoning. Is there an advantage of one therapy over the other? Why?", "options": [{"t": "Fomepizole: stronger alcohol dehydrogenase inhibitor, fewer adverse effects", "correct": true, "why": "Her key: fomepizole is a stronger alcohol dehydrogenase inhibitor and has fewer adverse effects than ethanol. On 10/19 she added that it gives better control of the dosing."}, {"t": "Ethanol: stronger alcohol dehydrogenase inhibitor, fewer adverse effects", "correct": false, "why": "Reversed. Her key gives both advantages to fomepizole."}, {"t": "Neither: the two are equal in strength and in adverse effects", "correct": false, "why": "Her key names an advantage: fomepizole."}, {"t": "Ethanol: a bottle can be kept on hand in the emergency room for a shot or two", "correct": false, "why": "Everclear was once kept in emergency rooms, but her key's answer favors fomepizole."}, {"t": "Fomepizole: it also chelates the toxic acid metabolites", "correct": false, "why": "Fomepizole acts on the enzyme; chelators bind metals."}], "teach": "Her key answers the special-considerations question: fomepizole is the stronger alcohol dehydrogenase inhibitor and has fewer adverse effects than ethanol. On 10/19 she described emergency rooms that once kept Everclear for a shot or two of ethanol, and said fomepizole gives better control of the dose.", "quote": "We now have, uh, the medication omeprazole that we'll give to patients. Um, a little bit better control of the dosing.", "note": "The transcript renders fomepizole as \"fomeprazole\" and \"omeprazole\"; omeprazole is a proton pump inhibitor, so this is a transcription error (see L16-008). L16-009 keys the dose-control point from her speech; the key adds strength and adverse effects.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Toxic alcohols’; transcript 10/19"},
{"id": "TBL3-011", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "recall", "concept": "tbl-benzo-symptoms", "tags": ["smith", "key"], "source": "slide", "stem": "Which entry gives the symptoms and diagnostic method for benzodiazepine overdose?", "options": [{"t": "Central nervous system (CNS) depression and relatively normal vitals; blood levels can be measured", "correct": true, "why": "The benzodiazepines row: CNS depression and relatively normal vitals; benzodiazepine levels can be measured in the blood."}, {"t": "Somnolence, coma, decreased heart and breath rates, decreased pupils", "correct": false, "why": "That is opioids: the heart and breathing rates fall, which is not \"relatively normal vitals\"."}, {"t": "Tachycardia, dilated pupils, dry mouth, agitation, seizures, elongated QRS interval, reduced cardiac contractility", "correct": false, "why": "That is tricyclic antidepressants."}, {"t": "Hypotension, bradycardia, but often alert", "correct": false, "why": "That is calcium channel blockers."}], "teach": "Her key: benzodiazepine overdose shows CNS depression with relatively normal vital signs, and benzodiazepine levels can be measured in the blood. The normal vitals separate it from the opioid picture, where heart and breathing rates fall.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Benzodiazepines’"},
{"id": "TBL3-012", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "drug", "concept": "tbl-benzo-antidote", "tags": ["smith", "key"], "source": "both", "stem": "What is the antidote for benzodiazepine overdose?", "options": [{"t": "Flumazenil", "correct": true, "why": "The benzodiazepines row: flumazenil."}, {"t": "Naloxone", "correct": false, "why": "Naloxone is the opioid antidote."}, {"t": "Atropine", "correct": false, "why": "Atropine is in the beta blocker and organophosphate rows."}, {"t": "Glucagon", "correct": false, "why": "Glucagon is in the beta blocker row."}, {"t": "Physostigmine", "correct": false, "why": "Physostigmine was the 10/19 example for belladonna alkaloids; it is not in the table."}], "teach": "Flumazenil is the benzodiazepine antidote. On 10/19 she gave it as an example of a treatment that is a receptor antagonist: the benzodiazepine agonizes the receptor and flumazenil antagonizes it.", "quote": "Flonazanil is used commonly for, uh, overdoses of things like your benzodiazepines.", "note": "The transcript renders flumazenil as \"Flonazanil\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Benzodiazepines’; transcript 10/19"},
{"id": "TBL3-013", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "drug", "concept": "tbl-benzo-moa", "tags": ["smith", "key"], "source": "both", "stem": "What is the mechanism of action of flumazenil?", "options": [{"t": "Competitive antagonist of the benzodiazepine receptor", "correct": true, "why": "The key's mechanism column: competitive antagonist of benzodiazepine receptor."}, {"t": "Competitive antagonist of opioid receptors", "correct": false, "why": "That is naloxone."}, {"t": "Muscarinic acetylcholine receptor antagonist", "correct": false, "why": "That is atropine, in the organophosphate row."}, {"t": "Binds the benzodiazepine, which is then renally eliminated", "correct": false, "why": "Binding and renal elimination is the digoxin antibody fragments row; flumazenil acts at the receptor."}, {"t": "Agonist at the benzodiazepine receptor", "correct": false, "why": "The benzodiazepine is the agonist; flumazenil is the antagonist."}], "teach": "Flumazenil is a competitive antagonist at the benzodiazepine receptor. The benzodiazepine in overdose is the agonist; the antidote competes with it at the same receptor. Naloxone does the same thing at the opioid receptor.", "quote": "Flonazanil is used commonly for, uh, overdoses of things like your benzodiazepines.", "note": "The transcript renders flumazenil as \"Flonazanil\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Benzodiazepines’; transcript 10/19", "dupOf": "L16-041"},
{"id": "TBL3-014", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "apply", "concept": "tbl-benzo-concern", "tags": ["smith", "key"], "source": "slide", "stem": "What are some concerns when choosing to use flumazenil?", "options": [{"t": "It can cause withdrawal symptoms in a benzodiazepine-dependent patient", "correct": true, "why": "Her key: flumazenil can cause withdrawal symptoms in a benzodiazepine dependent patient."}, {"t": "It loses effectiveness about 8 hours after the overdose", "correct": false, "why": "That is the acetaminophen antidote's time point."}, {"t": "It raises the total measured drug concentration, so levels cannot guide dosing", "correct": false, "why": "That is the digoxin antibody fragments special consideration."}, {"t": "It is a weaker inhibitor with more adverse effects than the alternative", "correct": false, "why": "That describes ethanol compared with fomepizole."}, {"t": "It is not specific to benzodiazepines", "correct": false, "why": "Flumazenil is a competitive antagonist of the benzodiazepine receptor."}], "teach": "The special-considerations question for benzodiazepines asks about concerns with flumazenil. Her key: it can cause withdrawal symptoms in a patient who is dependent on benzodiazepines. Naloxone carries the parallel concern in chronic opioid users.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Benzodiazepines’"},
{"id": "TBL3-015", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "recall", "concept": "tbl-bb-symptoms", "tags": ["smith", "key"], "source": "slide", "stem": "Which entry gives the symptoms of beta-blocker overdose?", "options": [{"t": "Hypotension, bradycardia, altered mental status, respiratory depression", "correct": true, "why": "The beta blockers row: hypotension, bradycardia, altered mental status, respiratory depression."}, {"t": "Hypotension, bradycardia, but often alert", "correct": false, "why": "That is calcium channel blockers; the alert mental status is the difference."}, {"t": "Bradycardia, arrhythmias, elevated serum potassium, nausea/vomiting; blood levels can be measured", "correct": false, "why": "That is digoxin."}, {"t": "Tachycardia, dilated pupils, dry mouth, agitation", "correct": false, "why": "That is tricyclic antidepressants."}, {"t": "Hypoglycemia", "correct": false, "why": "That is sulfonylureas and meglitinides."}], "teach": "Her key lists hypotension, bradycardia, altered mental status and respiratory depression for beta-blocker overdose. Calcium channel blocker overdose shares the hypotension and bradycardia, but the patient is often alert.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-016", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-antidotes", "tags": ["smith", "key"], "source": "slide", "multi": true, "stem": "Which of the following are listed as antidotes for beta-blocker overdose? Select all that apply.", "options": [{"t": "Atropine", "correct": true, "why": "Listed: atropine increases heart rate."}, {"t": "Calcium", "correct": true, "why": "Listed: calcium, to try to drive calcium into cardiac cells."}, {"t": "Glucagon", "correct": true, "why": "Listed: glucagon increases cardiac cellular cAMP to increase heart rate."}, {"t": "HIET", "correct": true, "why": "Listed as HIET; its inotropic mechanisms are not understood."}, {"t": "Vasopressors", "correct": true, "why": "Listed: vasopressors increase blood pressure."}, {"t": "Intravenous (IV) 20% fatty acid emulsion", "correct": true, "why": "Listed as IV FE: a sink for the drug if the drug is lipophilic enough."}, {"t": "Naloxone", "correct": false, "why": "Naloxone is the opioid antidote."}, {"t": "Octreotide", "correct": false, "why": "Octreotide is the sulfonylurea and meglitinide antidote."}, {"t": "Digoxin specific antibody fragments (digoxin immune Fab)", "correct": false, "why": "That is the digoxin antidote."}], "teach": "The beta blocker row lists six antidotes: atropine, calcium, glucagon, HIET, vasopressors and IV FE (intravenous 20% fatty acid emulsion). The calcium channel blocker row says \"same as above for BB OD\", so the same six apply there.", "note": "The key writes the abbreviation HIET without expanding it. The antidote column writes IV FE; the mechanism column writes \"i.v. 20% fatty acid emulsion\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-017", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-atropine", "tags": ["smith", "key"], "source": "slide", "stem": "In beta-blocker overdose, what is the mechanism of action listed for atropine?", "options": [{"t": "Increase heart rate", "correct": true, "why": "The key: Atropine: increase heart rate."}, {"t": "Drive calcium into cardiac cells", "correct": false, "why": "That is calcium."}, {"t": "Increase cardiac cellular cyclic AMP (cAMP)", "correct": false, "why": "That is glucagon."}, {"t": "Act as a sink for a lipophilic drug", "correct": false, "why": "That is the IV 20% fatty acid emulsion."}, {"t": "Increase blood pressure", "correct": false, "why": "That is the vasopressors."}], "teach": "Each of the six beta-blocker antidotes has its own entry in the mechanism column. Atropine increases heart rate, against the bradycardia of the overdose. In the organophosphate row, atropine is listed instead as a muscarinic acetylcholine receptor antagonist.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-018", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-calcium", "tags": ["smith", "key"], "source": "slide", "stem": "In beta-blocker or calcium channel blocker overdose, what is calcium given to do?", "options": [{"t": "Try to drive calcium into cardiac cells", "correct": true, "why": "The key: Calcium: try to drive calcium into cardiac cells."}, {"t": "Increase cardiac cellular cyclic AMP (cAMP) to increase heart rate", "correct": false, "why": "That is glucagon."}, {"t": "Chelate the overdosed drug in the plasma", "correct": false, "why": "Chelation is the deferoxamine and iron row; calcium is not a chelator."}, {"t": "Increase blood pressure by constricting vessels", "correct": false, "why": "The key lists blood pressure under the vasopressors."}, {"t": "Counteract the inhibition on sodium cardiac channels", "correct": false, "why": "That is sodium bicarbonate in the tricyclic antidepressant row."}], "teach": "Her key: calcium is given to try to drive calcium into cardiac cells. It is one of the six antidotes listed for beta-blocker overdose, and the calcium channel blocker row repeats the same list and mechanisms.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Beta blockers’, ‘Calcium channel blockers’"},
{"id": "TBL3-019", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-glucagon", "tags": ["smith", "key"], "source": "slide", "stem": "In beta-blocker overdose, what is the mechanism of action listed for glucagon?", "options": [{"t": "Increase cardiac cellular cAMP (cyclic AMP) to increase heart rate", "correct": true, "why": "The key: Glucagon: increase cardiac cellular cAMP to increase heart rate."}, {"t": "Inhibit insulin release from the pancreas", "correct": false, "why": "That is octreotide, in the sulfonylurea row."}, {"t": "Raise blood glucose to reverse hypoglycemia", "correct": false, "why": "The key's mechanism for glucagon is the cardiac cAMP effect; hypoglycemia is the sulfonylurea row."}, {"t": "Drive calcium into cardiac cells", "correct": false, "why": "That is calcium."}, {"t": "Block muscarinic acetylcholine receptors on the heart's pacemaker cells", "correct": false, "why": "Muscarinic receptor antagonist is the atropine entry in the organophosphate row."}], "teach": "Her key: glucagon increases cardiac cellular cAMP, and that increases heart rate. It is one of the six antidotes listed for beta-blocker overdose and, by the \"same as above\" entry, for calcium channel blocker overdose.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-020", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-hiet", "tags": ["smith", "key"], "source": "slide", "stem": "In beta-blocker overdose, what does the key say about the mechanism of HIET?", "options": [{"t": "The mechanisms of its inotropic effects are not understood", "correct": true, "why": "The key: HIET: mechanisms of inotropic effects not understood."}, {"t": "It chelates the overdosed drug so it can be renally eliminated", "correct": false, "why": "Chelation binds metals, as deferoxamine does for iron; her key says the mechanisms of HIET's inotropic effects are not understood."}, {"t": "It increases cardiac cellular cyclic AMP (cAMP)", "correct": false, "why": "That is glucagon."}, {"t": "It acts as a sink for a lipophilic drug", "correct": false, "why": "That is the IV 20% fatty acid emulsion."}, {"t": "It increases heart rate", "correct": false, "why": "That is atropine."}], "teach": "HIET is one of the six antidotes for beta-blocker overdose. The key gives no mechanism for it: the mechanisms of its inotropic effects are not understood. That entry is the answer to learn.", "note": "HIET is written as an abbreviation in her key and is not expanded there or in the transcript.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-021", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-pressors", "tags": ["smith", "key"], "source": "slide", "stem": "In beta-blocker overdose, what is the mechanism of action listed for vasopressors?", "options": [{"t": "Increase blood pressure", "correct": true, "why": "The key: vasopressors: increase blood pressure."}, {"t": "Increase heart rate", "correct": false, "why": "That is atropine (glucagon also raises heart rate, through cAMP)."}, {"t": "Drive calcium into cardiac cells", "correct": false, "why": "That is calcium."}, {"t": "Act as a sink for a lipophilic drug", "correct": false, "why": "That is the IV 20% fatty acid emulsion."}, {"t": "Enhance renal elimination by ion trapping", "correct": false, "why": "That is sodium bicarbonate in the salicylates row."}], "teach": "Her key: vasopressors increase blood pressure, against the hypotension of beta-blocker and calcium channel blocker overdose. In the tricyclic antidepressant row, dopamine or norepinephrine serve the same purpose, as supportive care to maintain blood pressure.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-022", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-fe", "tags": ["smith", "key"], "source": "slide", "stem": "In beta-blocker overdose, what mechanism does her key list for intravenous (IV) 20% fatty acid emulsion?", "options": [{"t": "It acts as a sink for the drug if the drug is lipophilic enough", "correct": true, "why": "The key: i.v. 20% fatty acid emulsion: acts as a sink for the drug if the drug is lipophilic enough."}, {"t": "It increases cardiac cellular cyclic AMP (cAMP)", "correct": false, "why": "That is glucagon."}, {"t": "It increases heart rate", "correct": false, "why": "That is atropine."}, {"t": "It binds the drug in an antibody complex that is renally eliminated", "correct": false, "why": "Binding and renal elimination is the digoxin antibody fragments row."}, {"t": "It increases blood pressure", "correct": false, "why": "That is the vasopressors."}], "teach": "The antidote column lists IV FE; the mechanism column spells it out as i.v. 20% fatty acid emulsion, which acts as a sink for the drug if the drug is lipophilic enough. The condition matters: the drug has to be lipophilic enough to move into the emulsion.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-023", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-bb-match", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each beta-blocker overdose antidote with the mechanism listed for it.", "left": ["Atropine", "Calcium", "Glucagon", "HIET", "Vasopressors", "Intravenous (IV) 20% fatty acid emulsion"], "right": ["Increase heart rate", "Try to drive calcium into cardiac cells", "Increase cardiac cellular cyclic AMP (cAMP) to increase heart rate", "Mechanisms of inotropic effects not understood", "Increase blood pressure", "Acts as a sink for the drug if the drug is lipophilic enough"], "pairs": [{"l": "Atropine", "r": "Increase heart rate", "why": "Atropine: increase heart rate."}, {"l": "Calcium", "r": "Try to drive calcium into cardiac cells", "why": "Calcium: try to drive calcium into cardiac cells."}, {"l": "Glucagon", "r": "Increase cardiac cellular cyclic AMP (cAMP) to increase heart rate", "why": "Glucagon: increase cardiac cellular cAMP to increase heart rate."}, {"l": "HIET", "r": "Mechanisms of inotropic effects not understood", "why": "HIET: mechanisms of inotropic effects not understood."}, {"l": "Vasopressors", "r": "Increase blood pressure", "why": "Vasopressors: increase blood pressure."}, {"l": "Intravenous (IV) 20% fatty acid emulsion", "r": "Acts as a sink for the drug if the drug is lipophilic enough", "why": "i.v. 20% fatty acid emulsion: acts as a sink for the drug if the drug is lipophilic enough."}], "teach": "The beta blocker row is the longest in the table: six antidotes, each with its own mechanism. Atropine and glucagon both raise heart rate (glucagon through cardiac cAMP); calcium is driven into cardiac cells; vasopressors raise blood pressure; the fatty acid emulsion is a sink for a lipophilic drug; HIET's inotropic mechanisms are not understood. The calcium channel blocker row repeats the list.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "TBL3-024", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "tell", "concept": "tbl-bb-vs-ccb", "tags": ["smith", "key"], "source": "slide", "stem": "What can distinguish between beta-blocker overdose and calcium channel blocker overdose?", "options": [{"t": "Beta-blocker overdose may have altered mental status", "correct": true, "why": "Her key: BB OD may have altered mental status; calcium channel blocker overdose is listed as often alert."}, {"t": "Calcium channel blocker overdose may have altered mental status", "correct": false, "why": "Reversed: the calcium channel blocker row says often alert."}, {"t": "Only beta-blocker overdose causes bradycardia", "correct": false, "why": "Both rows list bradycardia."}, {"t": "Only calcium channel blocker overdose causes hypotension", "correct": false, "why": "Both rows list hypotension."}, {"t": "They are treated with different antidotes", "correct": false, "why": "The calcium channel blocker row says \"same as above for BB OD\"."}], "teach": "Both overdoses cause hypotension and bradycardia, and the antidotes are the same. Her key's answer to the special-considerations question: the beta-blocker overdose may have altered mental status, while the calcium channel blocker patient is often alert.", "note": "Key abbreviations: BB OD is beta-blocker overdose.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Beta blockers’, ‘Calcium channel blockers’"},
{"id": "TBL3-025", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "recall", "concept": "tbl-ccb-symptoms", "tags": ["smith", "key"], "source": "slide", "stem": "Which entry gives the symptoms of calcium channel blocker overdose?", "options": [{"t": "Hypotension, bradycardia, but often alert", "correct": true, "why": "The calcium channel blockers row: hypotension, bradycardia, but often alert."}, {"t": "Hypotension, bradycardia, altered mental status, respiratory depression", "correct": false, "why": "That is beta blockers."}, {"t": "Somnolence, coma, decreased heart and breath rates, decreased pupils", "correct": false, "why": "That is opioids."}, {"t": "Tachycardia, dilated pupils, dry mouth, agitation, seizures", "correct": false, "why": "That is tricyclic antidepressants."}, {"t": "Hypoglycemia", "correct": false, "why": "That is sulfonylureas and meglitinides."}], "teach": "Her key: calcium channel blocker overdose causes hypotension and bradycardia, but the patient is often alert. That alertness is the answer to the beta blocker special-considerations question.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Calcium channel blockers’"},
{"id": "TBL3-026", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-ccb-antidotes", "tags": ["smith", "key"], "source": "slide", "stem": "What antidotes, with what mechanisms, are listed for calcium channel blocker overdose?", "options": [{"t": "The same as for beta-blocker overdose", "correct": true, "why": "Her key: \"Same as above for BB OD\" in both the antidote and the mechanism columns."}, {"t": "The beta-blocker list without glucagon", "correct": false, "why": "Her key says \"same as above for BB OD\", glucagon included."}, {"t": "Calcium alone", "correct": false, "why": "Calcium is one of six; the row repeats the whole beta-blocker list."}, {"t": "Digoxin specific antibody fragments", "correct": false, "why": "That is the digoxin antidote."}, {"t": "Intravenous fluids and sodium bicarbonate", "correct": false, "why": "That is the tricyclic antidepressant row."}], "teach": "The calcium channel blocker row does not list new antidotes: both the antidote and the mechanism columns read \"same as above for BB OD\". The six are atropine, calcium, glucagon, HIET, vasopressors and IV 20% fatty acid emulsion.", "note": "Keyed on her key, which repeats the full beta-blocker list for calcium channel blockers and leaves the special-considerations cell empty.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Calcium channel blockers’, ‘Beta blockers’"},
{"id": "TBL3-027", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-ccb-antidotes-sata", "tags": ["smith", "key"], "source": "slide", "multi": true, "stem": "Which of the following are listed as antidotes for calcium channel blocker overdose? Select all that apply.", "options": [{"t": "Atropine", "correct": true, "why": "Same as for beta-blocker overdose."}, {"t": "Calcium", "correct": true, "why": "Same as for beta-blocker overdose."}, {"t": "Glucagon", "correct": true, "why": "Same as for beta-blocker overdose; her key does not drop glucagon for calcium channel blockers."}, {"t": "HIET", "correct": true, "why": "Same as for beta-blocker overdose."}, {"t": "Vasopressors", "correct": true, "why": "Same as for beta-blocker overdose."}, {"t": "Intravenous (IV) 20% fatty acid emulsion", "correct": true, "why": "Same as for beta-blocker overdose."}, {"t": "Flumazenil", "correct": false, "why": "Flumazenil is the benzodiazepine antidote."}, {"t": "Sodium bicarbonate for an elongated QRS interval", "correct": false, "why": "That is the tricyclic antidepressant row; sodium bicarbonate is also in the salicylate row."}], "teach": "Her key's calcium channel blocker antidotes are \"same as above for BB OD\": atropine, calcium, glucagon, HIET, vasopressors and IV 20% fatty acid emulsion. The rows differ in symptoms (often alert), not in antidotes.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Calcium channel blockers’, ‘Beta blockers’", "dupOf": "TBL3-026"},
{"id": "TBL3-028", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "recall", "concept": "tbl-dig-symptoms", "tags": ["smith", "key"], "source": "slide", "stem": "Which entry gives the symptoms and diagnostic method for digoxin overdose?", "options": [{"t": "Bradycardia, arrhythmias, elevated serum potassium, nausea/vomiting; blood levels can be measured", "correct": true, "why": "The digoxin row: bradycardia, arrhythmias, elevated serum potassium, nausea/vomiting; digoxin levels can be measured in the blood."}, {"t": "Hypotension, bradycardia, but often alert", "correct": false, "why": "That is calcium channel blockers."}, {"t": "Hypoglycemia", "correct": false, "why": "That is sulfonylureas and meglitinides."}, {"t": "Tachycardia, dilated pupils, dry mouth, agitation, seizures, sometimes vasodilation, elongated QRS interval, reduced cardiac contractility", "correct": false, "why": "That is tricyclic antidepressants."}], "teach": "Her key for digoxin: bradycardia, arrhythmias, elevated serum potassium and nausea/vomiting, and digoxin levels can be measured in the blood. Elevated serum potassium is the finding no other row lists.", "note": "The key spells arrhythmias as \"arrythmias\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Digoxin’"},
{"id": "TBL3-029", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-dig-antidote", "tags": ["smith", "key"], "source": "both", "stem": "What is the antidote for digoxin overdose?", "options": [{"t": "Digoxin specific antibody fragments", "correct": true, "why": "The digoxin row: digoxin specific antibody fragments (Fab)."}, {"t": "Calcium and glucagon", "correct": false, "why": "Those are beta-blocker and calcium channel blocker antidotes."}, {"t": "Deferoxamine", "correct": false, "why": "That is the iron antidote."}, {"t": "Atropine and pralidoxime", "correct": false, "why": "Those are the organophosphate antidotes."}, {"t": "Intravenous fluids with dopamine or norepinephrine", "correct": false, "why": "That is the tricyclic antidepressant row."}], "teach": "Her key names digoxin specific antibody fragments (Fab) as the digoxin antidote. On 10/19 she called digoxin immune Fab an antibody made to grab digoxin and clear it from the blood. It is the example of inactivation by an antibody.", "quote": "One form of antibody made to grab digoxin that somebody's overdosed on, it grabs it and nicely clears it out of the blood.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Digoxin’; transcript 10/19"},
{"id": "TBL3-030", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "drug", "concept": "tbl-dig-moa", "tags": ["smith", "key"], "source": "both", "stem": "What is the mechanism of action of digoxin specific antibody fragments?", "options": [{"t": "Binds digoxin, which will be renally eliminated", "correct": true, "why": "The key: binds digoxin, will be renally eliminated."}, {"t": "Competitive antagonist of digoxin at its cardiac target", "correct": false, "why": "The antibody fragments bind the drug itself; they are not a receptor antagonist."}, {"t": "Chelates the circulating ferric iron", "correct": false, "why": "That is deferoxamine."}, {"t": "Increases cardiac cellular cyclic AMP (cAMP) to increase heart rate", "correct": false, "why": "That is glucagon."}, {"t": "Renal ion trapping to enhance elimination", "correct": false, "why": "That is sodium bicarbonate for salicylates; the antibody complex is renally eliminated, but by binding, not ion trapping."}], "teach": "Her key: the antibody fragments bind digoxin, and the bound complex will be renally eliminated. On 10/19 she described the antibody as grabbing digoxin and clearing it out of the blood.", "quote": "One form of antibody made to grab digoxin that somebody's overdosed on, it grabs it and nicely clears it out of the blood.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Digoxin’; transcript 10/19", "dupOf": "L16-038"},
{"id": "TBL3-031", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "apply", "concept": "tbl-dig-levels", "tags": ["smith", "key"], "source": "slide", "stem": "Once you give the antidote for digoxin overdose, digoxin specific antibody fragments (Fab), why is checking serum digoxin concentrations not helpful?", "options": [{"t": "Total digoxin (free and bound to Fab) is increased, so it cannot guide more Fab doses", "correct": true, "why": "Her key: the total dig concentration (free and bound to Fab) will be increased; you cannot use this measurement to calculate more Fab doses."}, {"t": "The antibody fragments clear digoxin within minutes, so the measured level reads zero", "correct": false, "why": "The key says the total concentration increases, not that it falls to zero."}, {"t": "The antibody fragments block the assay from detecting digoxin", "correct": false, "why": "The key says the measured total, free plus bound, goes up."}, {"t": "Digoxin levels cannot be measured in the blood", "correct": false, "why": "The symptoms column says digoxin levels can be measured in the blood."}], "teach": "Fab binds digoxin in the blood. After it is given, the total digoxin concentration, free plus bound to Fab, is increased, so the measured level no longer tells how much more Fab is needed. That is her key's answer to the special-considerations question.", "note": "Key abbreviations: \"dig\" is digoxin; Fab is the antibody fragments.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Digoxin’"},
{"id": "TBL3-032", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "recall", "concept": "tbl-tca-symptoms", "tags": ["smith", "key"], "source": "slide", "multi": true, "stem": "Which of the following are listed as symptoms of tricyclic antidepressant (TCA) overdose? Select all that apply.", "options": [{"t": "Tachycardia", "correct": true, "why": "Listed."}, {"t": "Dilated pupils", "correct": true, "why": "Listed."}, {"t": "Dry mouth", "correct": true, "why": "Listed."}, {"t": "Agitation and seizures", "correct": true, "why": "Both listed."}, {"t": "Elongated QRS interval", "correct": true, "why": "Listed; sodium bicarbonate is given for it."}, {"t": "Reduced cardiac contractility", "correct": true, "why": "Listed."}, {"t": "Sometimes vasodilation", "correct": true, "why": "Listed: sometimes vasodilation."}, {"t": "Bradycardia and elevated serum potassium", "correct": false, "why": "Those are in the digoxin row; TCA overdose lists tachycardia."}, {"t": "Decreased pupils", "correct": false, "why": "That is the opioid row; TCAs dilate the pupils."}], "teach": "Her key for TCAs: tachycardia, dilated pupils, dry mouth, agitation, seizures, sometimes vasodilation, elongated QRS interval and reduced cardiac contractility. On 10/14 she called TCA overdoses dangerous for the reduced sweating together with seizures.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Tricyclic Antidepressants’; transcript 10/14"},
{"id": "TBL3-033", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "drug", "concept": "tbl-tca-antidotes", "tags": ["smith", "key"], "source": "slide", "multi": true, "stem": "Which of the following are listed as treatments for tricyclic antidepressant (TCA) overdose? Select all that apply.", "options": [{"t": "Intravenous fluids", "correct": true, "why": "Listed: supportive care to maintain blood pressure."}, {"t": "Dopamine or norepinephrine", "correct": true, "why": "Listed: supportive care to maintain blood pressure."}, {"t": "Sodium bicarbonate for an elongated QRS interval", "correct": true, "why": "Listed: it counteracts the inhibition on sodium cardiac channels."}, {"t": "Flumazenil", "correct": false, "why": "Not in the TCA row; flumazenil is the benzodiazepine antidote."}, {"t": "Naloxone", "correct": false, "why": "Not in the TCA row; naloxone is the opioid antidote."}, {"t": "Deferoxamine to chelate the circulating ferric iron", "correct": false, "why": "Not in the TCA row; deferoxamine is the iron antidote."}], "teach": "Her key lists three treatments for TCA overdose: intravenous fluids, dopamine or norepinephrine, and sodium bicarbonate for an elongated QRS interval. The first two are supportive care to maintain blood pressure; the bicarbonate acts on the sodium channel problem.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Tricyclic Antidepressants’"},
{"id": "TBL3-034", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "drug", "concept": "tbl-tca-moa", "tags": ["smith", "key"], "source": "slide", "stem": "In tricyclic antidepressant overdose, what do intravenous fluids and dopamine or norepinephrine do, and what does sodium bicarbonate do?", "options": [{"t": "Fluids and pressors: supportive care for blood pressure; bicarbonate: counteracts sodium-channel inhibition", "correct": true, "why": "Her key: mostly supportive care, trying to maintain blood pressure; sodium bicarbonate counteracts the inhibition on sodium cardiac channels."}, {"t": "Fluids and pressors: supportive care for blood pressure; bicarbonate: renal ion trapping of the drug in the urine", "correct": false, "why": "Renal ion trapping is the bicarbonate mechanism in the salicylates row, not the TCA row."}, {"t": "Fluids and pressors: increase drug elimination; bicarbonate: chelates the drug", "correct": false, "why": "Neither entry is what the key says."}, {"t": "Fluids and pressors: antagonize the drug at its receptor; bicarbonate: replenishes glutathione", "correct": false, "why": "Neither entry is what the key says."}], "teach": "Her key's mechanism entry for TCAs: these options are mostly supportive care, trying to maintain blood pressure, and sodium bicarbonate counteracts the inhibition on sodium cardiac channels. The bicarbonate is given for the elongated QRS interval.", "note": "The row cites Basic and Clinical Pharmacology, Chapt 58, and has no special-considerations question.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Tricyclic Antidepressants’"},
{"id": "TBL3-035", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "tell", "concept": "tbl-bicarb-two-rows", "tags": ["smith", "key"], "source": "both", "stem": "Sodium bicarbonate appears in two rows of the table. Which pairing of poisoning and mechanism is correct?", "options": [{"t": "Tricyclic antidepressants: counteracts sodium-channel inhibition; salicylates: renal ion trapping", "correct": true, "why": "Her key: in the TCA row, sodium bicarbonate counteracts the inhibition on sodium cardiac channels; in the salicylates row, renal ion trapping to enhance elimination."}, {"t": "Tricyclic antidepressants: renal ion trapping; salicylates: counteracts sodium-channel inhibition", "correct": false, "why": "Reversed."}, {"t": "Both: renal ion trapping to enhance elimination", "correct": false, "why": "Only the salicylates row gives ion trapping."}, {"t": "Both: counteracts the inhibition on sodium cardiac channels", "correct": false, "why": "Only the TCA row gives the sodium channel mechanism."}], "teach": "The same drug carries two mechanisms in the table. For salicylates, IV sodium bicarbonate makes the urine more basic so the weak acid is trapped and eliminated (renal ion trapping). For tricyclic antidepressants, sodium bicarbonate is given for an elongated QRS interval and counteracts the inhibition on sodium cardiac channels.", "quote": "So if we have a person that's overdosed on salicylates on some of our barbiturates, they are mildly acidic. ... We'll hang a bag of sodium bicarb on a patient, that'll make their urine a bit more basic", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Tricyclic Antidepressants’, ‘Salicylates’; transcript 10/19"},
{"id": "TBL3-036", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "recall", "concept": "tbl-opioid-symptoms", "tags": ["smith", "key"], "source": "slide", "stem": "Which entry gives the symptoms of opioid overdose?", "options": [{"t": "Somnolence, coma, decreased heart and breath rates, decreased pupils", "correct": true, "why": "The opioids row: somnolence, coma, decreased heart and breath rates, decrease pupils."}, {"t": "Somnolence, coma, decreased heart and breath rates, dilated pupils", "correct": false, "why": "The pupils are decreased in opioid overdose; dilated pupils are the tricyclic antidepressant row."}, {"t": "Central nervous system depression and relatively normal vitals; blood levels measurable", "correct": false, "why": "That is benzodiazepines."}, {"t": "Hypotension, bradycardia, but often alert", "correct": false, "why": "That is calcium channel blockers."}, {"t": "Hyperventilation and respiratory alkalosis, then metabolic acidosis", "correct": false, "why": "That is salicylates."}], "teach": "Her key: somnolence, coma, decreased heart and breath rates, and decreased pupils. The falling heart and breathing rates separate opioids from benzodiazepines, whose vitals are relatively normal.", "note": "The key writes \"decrease pupils\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Opioids’"},
{"id": "TBL3-037", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "drug", "concept": "tbl-opioid-antidote", "tags": ["smith", "key"], "source": "both", "stem": "What is the antidote for opioid overdose?", "options": [{"t": "Naloxone", "correct": true, "why": "The opioids row: naloxone."}, {"t": "Flumazenil", "correct": false, "why": "That is the benzodiazepine antidote."}, {"t": "Octreotide", "correct": false, "why": "That is the sulfonylurea and meglitinide antidote."}, {"t": "Atropine", "correct": false, "why": "Atropine is in the beta blocker and organophosphate rows."}, {"t": "N-acetylcysteine", "correct": false, "why": "That is the acetaminophen antidote."}], "teach": "Naloxone is the opioid antidote. On 10/19 she used it as the first example of a treatment that is a receptor antagonist.", "quote": "Naloxone is basically an antagonist of an opioid receptor", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Opioids’; transcript 10/19"},
{"id": "TBL3-038", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "drug", "concept": "tbl-opioid-moa", "tags": ["smith", "key"], "source": "both", "stem": "What is the mechanism of action of naloxone?", "options": [{"t": "Competitive antagonist of opioid receptors", "correct": true, "why": "The key: competitive antagonist of opioid receptors."}, {"t": "Competitive antagonist of the benzodiazepine receptor", "correct": false, "why": "That is flumazenil."}, {"t": "Muscarinic acetylcholine receptor antagonist", "correct": false, "why": "That is atropine in the organophosphate row."}, {"t": "Binds the opioid, which is then renally eliminated", "correct": false, "why": "Binding and renal elimination is the digoxin antibody fragments row."}, {"t": "Inhibits insulin release from the pancreas", "correct": false, "why": "That is octreotide."}], "teach": "Her key: naloxone is a competitive antagonist of opioid receptors. The overdosed opioid is the agonist; naloxone competes with it at the receptor. Flumazenil is the same kind of treatment at the benzodiazepine receptor.", "quote": "Naloxone is basically an antagonist of an opioid receptor", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Opioids’; transcript 10/19", "dupOf": "L16-040"},
{"id": "TBL3-039", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "apply", "concept": "tbl-opioid-withdrawal", "tags": ["smith", "key"], "source": "slide", "stem": "What is a concern when using naloxone in chronic opioid users?", "options": [{"t": "It can trigger withdrawal", "correct": true, "why": "Her key: it can trigger withdrawal."}, {"t": "It loses effectiveness about 8 hours after overdose", "correct": false, "why": "That is the acetaminophen antidote."}, {"t": "It causes renal toxicity", "correct": false, "why": "Renal toxicity is listed for ethylene glycol, not for naloxone."}, {"t": "It raises the total measured drug level", "correct": false, "why": "That is the digoxin antibody fragments special consideration."}, {"t": "It has more adverse effects than the alternative", "correct": false, "why": "That describes ethanol compared with fomepizole."}], "teach": "Her key's answer to the opioid special-considerations question: in chronic opioid users, naloxone can trigger withdrawal. Flumazenil carries the parallel concern in benzodiazepine-dependent patients.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Opioids’"},
{"id": "TBL3-040", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "tell", "concept": "tbl-withdrawal-pair", "tags": ["smith", "key"], "source": "slide", "stem": "Which two antidotes carry the concern that they can cause withdrawal in a dependent patient?", "options": [{"t": "Flumazenil and naloxone", "correct": true, "why": "Flumazenil: withdrawal symptoms in a benzodiazepine-dependent patient. Naloxone: can trigger withdrawal in chronic opioid users."}, {"t": "Naloxone and N-acetylcysteine", "correct": false, "why": "The N-acetylcysteine concern is its time point (about 8 hours), not withdrawal."}, {"t": "Flumazenil and fomepizole", "correct": false, "why": "The fomepizole entry is its advantage over ethanol, not withdrawal."}, {"t": "Digoxin specific antibody fragments and naloxone", "correct": false, "why": "The antibody fragments concern is the misleading serum level, not withdrawal."}], "teach": "Two of the receptor antagonists in the table carry the same concern. Flumazenil can cause withdrawal symptoms in a benzodiazepine-dependent patient, and naloxone can trigger withdrawal in chronic opioid users. Both compete with the overdosed agonist at its receptor.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Benzodiazepines’, ‘Opioids’"},
{"id": "TBL3-041", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "concept": "tbl-sal-symptoms", "tags": ["smith", "key"], "source": "both", "stem": "In salicylate poisoning, which sequence of findings is listed?", "options": [{"t": "Hyperventilation and respiratory alkalosis, then metabolic acidosis", "correct": true, "why": "The salicylates row: hyperventilation and respiratory alkalosis then metabolic acidosis, hyperthermia, confusion and seizures."}, {"t": "Metabolic acidosis first, then hyperventilation and respiratory alkalosis", "correct": false, "why": "Reversed: the respiratory alkalosis comes first."}, {"t": "Anion-gap metabolic acidosis with ocular toxicity", "correct": false, "why": "That is methanol."}, {"t": "Hypoglycemia", "correct": false, "why": "Hypoglycemia is the sulfonylurea row."}, {"t": "Metabolic alkalosis only", "correct": false, "why": "The key lists respiratory alkalosis, then metabolic acidosis."}], "teach": "Her key for salicylates: hyperventilation and respiratory alkalosis, then metabolic acidosis, along with hyperthermia, confusion and seizures. Salicylates were also on her 10/19 list of compounds emergency rooms test the blood for.", "quote": "Acetaminophen, OK, acetaminophen. Salicylates Iron Beta blockers, calcium channel blockers, and there's a few others", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Salicylates’; transcript 10/19"},
{"id": "TBL3-042", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "concept": "tbl-sal-other", "tags": ["smith", "key"], "source": "slide", "stem": "Besides the acid-base changes, which findings are listed for salicylate poisoning?", "options": [{"t": "Hyperthermia, confusion and seizures", "correct": true, "why": "The salicylates row: hyperthermia, confusion and seizures."}, {"t": "Ocular toxicity and blindness", "correct": false, "why": "That is methanol."}, {"t": "Elevated serum potassium and arrhythmias", "correct": false, "why": "That is digoxin."}, {"t": "Somnolence, coma and decreased pupils", "correct": false, "why": "That is opioids."}, {"t": "Hypoglycemia", "correct": false, "why": "That is sulfonylureas and meglitinides."}], "teach": "The salicylates row lists hyperventilation and respiratory alkalosis, then metabolic acidosis, plus hyperthermia, confusion and seizures. Learn the acid-base sequence and the three added findings together.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Salicylates’"},
{"id": "TBL3-043", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-sal-antidote", "tags": ["smith", "key"], "source": "both", "stem": "What treatment is listed for salicylate poisoning?", "options": [{"t": "Supportive care, intravenous (IV) sodium bicarbonate", "correct": true, "why": "The salicylates row: supportive care, IV sodium bicarbonate."}, {"t": "Ethanol or fomepizole, to block alcohol dehydrogenase", "correct": false, "why": "That is the toxic alcohols row."}, {"t": "Octreotide", "correct": false, "why": "That is the sulfonylurea and meglitinide antidote."}, {"t": "Naloxone", "correct": false, "why": "That is the opioid antidote."}, {"t": "Deferoxamine", "correct": false, "why": "That is the iron antidote."}], "teach": "Salicylate poisoning is treated with supportive care and intravenous sodium bicarbonate. On 10/19 she used salicylates as the example of ion trapping: a bag of sodium bicarbonate makes the urine more basic.", "quote": "So if we have a person that's overdosed on salicylates on some of our barbiturates, they are mildly acidic. ... We'll hang a bag of sodium bicarb on a patient, that'll make their urine a bit more basic", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Salicylates’; transcript 10/19"},
{"id": "TBL3-044", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-sal-moa", "tags": ["smith", "key"], "source": "both", "stem": "What is the mechanism of intravenous (IV) sodium bicarbonate in salicylate poisoning?", "options": [{"t": "Renal ion trapping to enhance elimination", "correct": true, "why": "The key: renal ion trapping to enhance elimination."}, {"t": "Counteracts the inhibition on sodium cardiac channels", "correct": false, "why": "That is the bicarbonate mechanism in the tricyclic antidepressant row."}, {"t": "Inhibition of alcohol dehydrogenase", "correct": false, "why": "That is ethanol or fomepizole."}, {"t": "Chelates the salicylate in the plasma", "correct": false, "why": "Chelation is for metals such as iron."}, {"t": "Replenishes glutathione", "correct": false, "why": "That is N-acetylcysteine."}], "teach": "Her key: renal ion trapping to enhance elimination. Salicylate is mildly acidic; bicarbonate makes the urine more basic, the salicylate carries a negative charge there, and the charged molecule is not reabsorbed. That is the toxicokinetic treatment of enhancing renal elimination.", "quote": "So if we have a person that's overdosed on salicylates on some of our barbiturates, they are mildly acidic. ... We'll hang a bag of sodium bicarb on a patient, that'll make their urine a bit more basic", "note": "The row cites Basic and Clinical Pharmacology, Chapt 58, and has no special-considerations question.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Salicylates’; transcript 10/19", "dupOf": "L16-024"},
{"id": "TBL3-045", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "concept": "tbl-su-symptom", "tags": ["smith", "key"], "source": "slide", "stem": "Which symptom is listed for sulfonylurea and meglitinide overdose?", "options": [{"t": "Hypoglycemia", "correct": true, "why": "The sulfonylureas and meglitinides row: hypoglycemia."}, {"t": "Hyperthermia", "correct": false, "why": "That is salicylates."}, {"t": "Elevated serum potassium", "correct": false, "why": "That is digoxin."}, {"t": "Ocular toxicity", "correct": false, "why": "That is methanol."}, {"t": "Dilated pupils", "correct": false, "why": "That is tricyclic antidepressants."}], "teach": "The sulfonylurea and meglitinide row has a single symptom: hypoglycemia. The antidote, octreotide, works on the insulin release that causes it.", "note": "The key spells meglitinide as \"miglitinide\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Sulfonylureas and miglitinide’"},
{"id": "TBL3-046", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-su-antidote", "tags": ["smith", "key"], "source": "slide", "stem": "What is the antidote for sulfonylurea and meglitinide overdose?", "options": [{"t": "Octreotide", "correct": true, "why": "The sulfonylureas and meglitinides row: octreotide."}, {"t": "Glucagon", "correct": false, "why": "Glucagon is listed in the beta blocker row, for its cardiac cAMP effect."}, {"t": "Naloxone", "correct": false, "why": "That is the opioid antidote."}, {"t": "Flumazenil", "correct": false, "why": "That is the benzodiazepine antidote."}, {"t": "Deferoxamine", "correct": false, "why": "That is the iron antidote."}], "teach": "Her key names octreotide as the sulfonylurea and meglitinide antidote. Glucagon is in the table too, but in the beta blocker row.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Sulfonylureas and miglitinide’"},
{"id": "TBL3-047", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "drug", "concept": "tbl-su-moa", "tags": ["smith", "key"], "source": "slide", "stem": "What is the mechanism of action of octreotide in sulfonylurea overdose?", "options": [{"t": "Inhibits insulin release from the pancreas", "correct": true, "why": "The key: inhibits insulin release from the pancreas."}, {"t": "Stimulates insulin release from the pancreas", "correct": false, "why": "Reversed. Octreotide inhibits insulin release."}, {"t": "Increases cardiac cellular cyclic AMP (cAMP) to increase heart rate", "correct": false, "why": "That is glucagon."}, {"t": "Replenishes glutathione", "correct": false, "why": "That is N-acetylcysteine."}, {"t": "Competitive antagonist of opioid receptors", "correct": false, "why": "That is naloxone."}], "teach": "Her key: octreotide inhibits insulin release from the pancreas. The overdose causes hypoglycemia; holding back insulin release treats it. The row has no special-considerations question.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Sulfonylureas and miglitinide’"},
{"id": "TBL3-048", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "recall", "concept": "tbl-iron-timeline", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each time after an iron overdose with the findings listed for it.", "left": ["Within 1 to 6 hours", "Within 6 to 24 hours", "In 2 to 5 days"], "right": ["Vomiting, abdominal pain and diarrhea", "Lethargy, coma, seizures, bloody vomiting, bloody diarrhea, shock, hypotension and tachycardia", "Liver dysfunction and failure possible"], "pairs": [{"l": "Within 1 to 6 hours", "r": "Vomiting, abdominal pain and diarrhea", "why": "The first bullet of the iron row."}, {"l": "Within 6 to 24 hours", "r": "Lethargy, coma, seizures, bloody vomiting, bloody diarrhea, shock, hypotension and tachycardia", "why": "The second and third bullets, both within 6 to 24 hours."}, {"l": "In 2 to 5 days", "r": "Liver dysfunction and failure possible", "why": "The last bullet of the iron row."}], "teach": "Her key gives iron a timeline. Within 1 to 6 hours: vomiting, abdominal pain and diarrhea. Within 6 to 24 hours: lethargy, coma, seizures, bloody vomiting, bloody diarrhea and shock, with hypotension and tachycardia. Liver dysfunction and failure are possible in 2 to 5 days.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Iron’"},
{"id": "TBL3-049", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "recall", "concept": "tbl-iron-early", "tags": ["smith", "key"], "source": "slide", "stem": "Within what time after an iron overdose do vomiting, abdominal pain and diarrhea appear?", "options": [{"t": "1 to 6 hours", "correct": true, "why": "Her key: vomiting, abdominal pain and diarrhea within 1 to 6 hours."}, {"t": "6 to 24 hours", "correct": false, "why": "That window is for lethargy, coma, seizures, bloody vomiting, bloody diarrhea, shock, hypotension and tachycardia."}, {"t": "2 to 5 days", "correct": false, "why": "That is when liver dysfunction and failure are possible."}, {"t": "About 8 hours", "correct": false, "why": "About 8 hours is the acetaminophen antidote's time point."}], "teach": "The iron row gives three windows: 1 to 6 hours for vomiting, abdominal pain and diarrhea; 6 to 24 hours for lethargy, coma, seizures, bloody vomiting and diarrhea, shock, hypotension and tachycardia; 2 to 5 days for possible liver dysfunction and failure.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Iron’"},
{"id": "TBL3-050", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "recall", "concept": "tbl-iron-late", "tags": ["smith", "key"], "source": "slide", "stem": "In iron overdose, when are liver dysfunction and failure possible?", "options": [{"t": "In 2 to 5 days", "correct": true, "why": "Her key: liver dysfunction and failure possible in 2 to 5 days."}, {"t": "Within 1 to 6 hours", "correct": false, "why": "That is the window for vomiting, abdominal pain and diarrhea."}, {"t": "Within 6 to 24 hours", "correct": false, "why": "That is the window for lethargy, coma, seizures, bloody vomiting and diarrhea, shock, hypotension and tachycardia."}, {"t": "After 2 weeks", "correct": false, "why": "Her key gives 2 to 5 days."}], "teach": "Liver involvement is the last step of the iron timeline: liver dysfunction and failure are possible in 2 to 5 days. The gastrointestinal symptoms come first, within 1 to 6 hours.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Iron’"},
{"id": "TBL3-051", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "drug", "concept": "tbl-iron-antidote", "tags": ["smith", "key"], "source": "both", "stem": "What is the antidote for iron overdose?", "options": [{"t": "Deferoxamine", "correct": true, "why": "The iron row: deferoxamine."}, {"t": "Dimercaprol", "correct": false, "why": "On the 10/19 chelator table, dimercaprol chelates gold, arsenic, lead and mercury."}, {"t": "Penicillamine", "correct": false, "why": "On the 10/19 chelator table, penicillamine chelates copper."}, {"t": "Pralidoxime", "correct": false, "why": "That is an organophosphate antidote."}, {"t": "Octreotide", "correct": false, "why": "That is the sulfonylurea and meglitinide antidote."}], "teach": "Her key names deferoxamine as the iron antidote. On 10/19 she said two iron chelators have been on the market, deferoxamine and the oral deferasirox; the table lists deferoxamine.", "quote": "We have had two iron chelating agents on the market now, differoxyzine and differracerro.", "note": "The transcript renders deferoxamine and deferasirox as \"differoxyzine\" and \"differracerro\". The iron row cites Pharmacotherapy: A Pathophysiologic Approach, 13th Ed. Chapt e6, while on 10/19 she pointed to DiPiro chapter e9 for the table.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Iron’; transcript 10/19; Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Example Chelating Agents’"},
{"id": "TBL3-052", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "drug", "concept": "tbl-iron-moa", "tags": ["smith", "key"], "source": "slide", "stem": "What is the mechanism of action of deferoxamine?", "options": [{"t": "Chelates the circulating ferric iron", "correct": true, "why": "The key: chelates the circulating ferric iron."}, {"t": "Removes the iron from its target enzyme", "correct": false, "why": "Removing a poison from an enzyme is the pralidoxime entry, for organophosphates."}, {"t": "Binds iron, which is then renally eliminated as an antibody complex", "correct": false, "why": "Antibody binding and renal elimination is the digoxin antibody fragments row."}, {"t": "Renal ion trapping to enhance elimination", "correct": false, "why": "That is sodium bicarbonate for salicylates."}, {"t": "Inhibition of alcohol dehydrogenase", "correct": false, "why": "That is ethanol or fomepizole."}], "teach": "Her key: deferoxamine chelates the circulating ferric iron. It is the iron entry of the inactivation approach, with heavy metal chelators binding the metal so it cannot act. The row has no special-considerations question.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Iron’"},
{"id": "TBL3-053", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "recall", "concept": "tbl-op-symptoms", "tags": ["smith", "key"], "source": "both", "stem": "Which entry gives the symptoms of organophosphate insecticide poisoning?", "options": [{"t": "Acetylcholine excess: SLUDGE or DUMBELLS", "correct": true, "why": "The organophosphate row: acetylcholine excess, SLUDGE or DUMBELLS."}, {"t": "Tachycardia, dilated pupils, dry mouth, agitation", "correct": false, "why": "That is the tricyclic antidepressant row."}, {"t": "Somnolence, coma, decreased heart and breath rates, decreased pupils", "correct": false, "why": "That is opioids."}, {"t": "Hypotension, bradycardia, but often alert", "correct": false, "why": "That is calcium channel blockers."}, {"t": "Central nervous system depression with relatively normal vitals", "correct": false, "why": "That is benzodiazepines."}], "teach": "Her key: organophosphate insecticides cause acetylcholine excess, recalled as SLUDGE or DUMBELLS. On 10/19 she explained that organophosphates inhibit acetylcholinesterase, so acetylcholine builds up in the synaptic cleft.", "quote": "So if you are exposed to organophosphate pesticides, you end up with too much acetylcholine in your synaptic cleft. And we'll use atropine to antagonize that.", "note": "The key gives the mnemonics SLUDGE and DUMBELLS without spelling out the letters.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Organophosphate Insecticides’; transcript 10/19"},
{"id": "TBL3-054", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "drug", "concept": "tbl-op-antidotes", "tags": ["smith", "key"], "source": "both", "multi": true, "stem": "Which of the following are listed as antidotes for organophosphate insecticide poisoning? Select all that apply.", "options": [{"t": "Atropine", "correct": true, "why": "Listed: a muscarinic acetylcholine receptor antagonist."}, {"t": "Pralidoxime", "correct": true, "why": "Listed: removes the organophosphate from acetylcholinesterase."}, {"t": "Physostigmine", "correct": false, "why": "Physostigmine was her 10/19 example of a treatment that is a receptor agonist, for belladonna alkaloids; it is not in the table."}, {"t": "Flumazenil", "correct": false, "why": "That is the benzodiazepine antidote."}, {"t": "Glucagon", "correct": false, "why": "That is a beta-blocker antidote."}], "teach": "Her key lists two organophosphate antidotes: atropine and pralidoxime. Atropine blocks the effects of the excess acetylcholine at muscarinic receptors; pralidoxime removes the organophosphate from acetylcholinesterase.", "quote": "One of the things that we can do is to pull off the organophosphate by using pralodoxine. What you'll see here is, here's pralodoxine here. And it's gonna pull off the organophosphate and put it onto itself. And when it does that, it can be eliminated.", "note": "The transcript renders pralidoxime as \"pralodoxine\". The row cites Pharmacotherapy: A Pathophysiologic Approach, 13th Ed. Chapt e6.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Organophosphate Insecticides’; transcript 10/19"},
{"id": "TBL3-055", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "drug", "concept": "tbl-op-atropine", "tags": ["smith", "key"], "source": "both", "stem": "In organophosphate poisoning, what is the mechanism of action listed for atropine?", "options": [{"t": "Muscarinic acetylcholine receptor antagonist", "correct": true, "why": "The key: muscarinic acetylcholine receptor antagonist."}, {"t": "Removes the organophosphate from acetylcholinesterase", "correct": false, "why": "That is pralidoxime."}, {"t": "Inhibits acetylcholinesterase", "correct": false, "why": "That is what the organophosphate does."}, {"t": "Increases cardiac cellular cyclic AMP (cAMP)", "correct": false, "why": "That is glucagon."}, {"t": "Competitive antagonist of the benzodiazepine receptor", "correct": false, "why": "That is flumazenil."}], "teach": "Her key: atropine is a muscarinic acetylcholine receptor antagonist. The organophosphate has inhibited acetylcholinesterase, acetylcholine builds up, and atropine antagonizes it at the receptor. On 10/19 this was her example of a treatment that is a receptor antagonist.", "quote": "So if you are exposed to organophosphate pesticides, you end up with too much acetylcholine in your synaptic cleft. And we'll use atropine to antagonize that.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Organophosphate Insecticides’; transcript 10/19", "dupOf": "L16-042"},
{"id": "TBL3-056", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "drug", "concept": "tbl-op-pralidoxime", "tags": ["smith", "key"], "source": "both", "stem": "What is the mechanism of action of pralidoxime?", "options": [{"t": "Removes organophosphate (OP) from acetylcholinesterase", "correct": true, "why": "The key: removes OP from acetylcholinesterase."}, {"t": "Muscarinic acetylcholine receptor antagonist", "correct": false, "why": "That is atropine."}, {"t": "Chelates the organophosphate in the blood", "correct": false, "why": "Chelation is the iron row; pralidoxime acts on the enzyme."}, {"t": "Breaks down the excess acetylcholine in the synaptic cleft", "correct": false, "why": "Acetylcholinesterase does that once it is freed."}, {"t": "Inhibition of alcohol dehydrogenase", "correct": false, "why": "That is ethanol or fomepizole."}], "teach": "Her key: pralidoxime removes the organophosphate from acetylcholinesterase. On 10/19 she showed it pulling the organophosphate off the enzyme onto itself, after which the complex can be eliminated. It is the example of removing the toxin from its active site.", "quote": "One of the things that we can do is to pull off the organophosphate by using pralodoxine. What you'll see here is, here's pralodoxine here. And it's gonna pull off the organophosphate and put it onto itself. And when it does that, it can be eliminated.", "note": "The transcript renders pralidoxime as \"pralodoxine\".", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Organophosphate Insecticides’; transcript 10/19", "dupOf": "L16-046"},
{"id": "TBL3-057", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "tell", "concept": "tbl-atropine-two-rows", "tags": ["smith", "key"], "source": "slide", "stem": "Atropine appears in two rows of the table. Which pairing of poisoning and listed mechanism is correct?", "options": [{"t": "Beta blockers: increase heart rate; organophosphates: muscarinic receptor antagonist", "correct": true, "why": "Her key: in the beta blocker row, atropine: increase heart rate; in the organophosphate row, muscarinic acetylcholine receptor antagonist."}, {"t": "Beta blockers: muscarinic receptor antagonist; organophosphates: increase heart rate", "correct": false, "why": "Reversed."}, {"t": "Both: removes the organophosphate from acetylcholinesterase", "correct": false, "why": "That is pralidoxime."}, {"t": "Both: increase cardiac cellular cyclic AMP (cAMP)", "correct": false, "why": "That is glucagon."}], "teach": "The key states atropine's mechanism differently in the two rows. For beta-blocker overdose, it is listed by its effect, increasing heart rate. For organophosphates, it is listed by its action, a muscarinic acetylcholine receptor antagonist against the acetylcholine excess.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Beta blockers’, ‘Organophosphate Insecticides’"},
{"id": "TBL3-058", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "recall", "concept": "tbl-blood-levels", "tags": ["smith", "key"], "source": "slide", "multi": true, "stem": "For which poisonings does the table list a blood level as a diagnostic method? Select all that apply.", "options": [{"t": "Acetaminophen", "correct": true, "why": "Acetaminophen levels can be measured in the blood."}, {"t": "Benzodiazepines", "correct": true, "why": "Benzodiazepine levels can be measured in the blood."}, {"t": "Digoxin", "correct": true, "why": "Digoxin levels can be measured in the blood."}, {"t": "Sulfonylureas and meglitinides", "correct": false, "why": "That row lists hypoglycemia only."}, {"t": "Tricyclic antidepressants", "correct": false, "why": "That row lists symptoms and the elongated QRS interval, no blood level."}, {"t": "Organophosphate insecticides", "correct": false, "why": "That row lists acetylcholine excess (SLUDGE or DUMBELLS), no blood level."}], "teach": "Three rows of the key add a blood measurement to the symptoms: acetaminophen, benzodiazepines and digoxin. For digoxin the special-considerations question adds that the level stops being useful once Fab is given.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Acetaminophen’, ‘Benzodiazepines’, ‘Digoxin’"},
{"id": "TBL3-059", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "drug", "concept": "tbl-match-antidote-1", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each poisoning with its antidote.", "left": ["Acetaminophen", "Toxic alcohols", "Benzodiazepines", "Opioids", "Digoxin", "Sulfonylureas and meglitinides"], "right": ["N-acetylcysteine", "Ethanol or fomepizole", "Flumazenil", "Naloxone", "Digoxin specific antibody fragments", "Octreotide"], "pairs": [{"l": "Acetaminophen", "r": "N-acetylcysteine", "why": "Acetaminophen row."}, {"l": "Toxic alcohols", "r": "Ethanol or fomepizole", "why": "Toxic alcohols row."}, {"l": "Benzodiazepines", "r": "Flumazenil", "why": "Benzodiazepines row."}, {"l": "Opioids", "r": "Naloxone", "why": "Opioids row."}, {"l": "Digoxin", "r": "Digoxin specific antibody fragments", "why": "Digoxin row."}, {"l": "Sulfonylureas and meglitinides", "r": "Octreotide", "why": "Sulfonylureas and meglitinides row."}], "teach": "Six rows with one antidote each (two choices for the toxic alcohols): acetaminophen, N-acetylcysteine; toxic alcohols, ethanol or fomepizole; benzodiazepines, flumazenil; opioids, naloxone; digoxin, digoxin specific antibody fragments; sulfonylureas and meglitinides, octreotide.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Acetaminophen’, ‘Toxic alcohols’, ‘Benzodiazepines’, ‘Opioids’, ‘Digoxin’, ‘Sulfonylureas and miglitinide’"},
{"id": "TBL3-060", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "drug", "concept": "tbl-match-antidote-2", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each poisoning with the antidotes or treatments listed for it.", "left": ["Beta blockers or calcium channel blockers", "Tricyclic antidepressants", "Salicylates", "Iron", "Organophosphate insecticides"], "right": ["Atropine, calcium, glucagon, HIET, vasopressors, intravenous fatty acid emulsion (IV FE)", "Intravenous fluids, dopamine or norepinephrine, sodium bicarbonate for elongated QRS interval", "Supportive care, intravenous sodium bicarbonate", "Deferoxamine", "Atropine and pralidoxime"], "pairs": [{"l": "Beta blockers or calcium channel blockers", "r": "Atropine, calcium, glucagon, HIET, vasopressors, intravenous fatty acid emulsion (IV FE)", "why": "The beta blocker row; the calcium channel blocker row says same as above."}, {"l": "Tricyclic antidepressants", "r": "Intravenous fluids, dopamine or norepinephrine, sodium bicarbonate for elongated QRS interval", "why": "Tricyclic antidepressants row."}, {"l": "Salicylates", "r": "Supportive care, intravenous sodium bicarbonate", "why": "Salicylates row."}, {"l": "Iron", "r": "Deferoxamine", "why": "Iron row."}, {"l": "Organophosphate insecticides", "r": "Atropine and pralidoxime", "why": "Organophosphate row."}], "teach": "The rows with several treatments: beta blockers and calcium channel blockers share six antidotes; tricyclic antidepressants get intravenous fluids, dopamine or norepinephrine, and sodium bicarbonate for an elongated QRS interval; salicylates get supportive care and IV sodium bicarbonate; organophosphates get atropine and pralidoxime. Iron gets deferoxamine.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Beta blockers’, ‘Calcium channel blockers’, ‘Tricyclic Antidepressants’, ‘Salicylates’, ‘Iron’, ‘Organophosphate Insecticides’"},
{"id": "TBL3-061", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "drug", "concept": "tbl-match-moa-1", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each antidote with its mechanism of action.", "left": ["N-acetylcysteine", "Ethanol or fomepizole", "Flumazenil", "Naloxone", "Digoxin specific antibody fragments", "Octreotide"], "right": ["Replenishes glutathione", "Inhibition of alcohol dehydrogenase", "Competitive antagonist of benzodiazepine receptor", "Competitive antagonist of opioid receptors", "Binds digoxin, will be renally eliminated", "Inhibits insulin release from the pancreas"], "pairs": [{"l": "N-acetylcysteine", "r": "Replenishes glutathione", "why": "Acetaminophen row."}, {"l": "Ethanol or fomepizole", "r": "Inhibition of alcohol dehydrogenase", "why": "Toxic alcohols row."}, {"l": "Flumazenil", "r": "Competitive antagonist of benzodiazepine receptor", "why": "Benzodiazepines row."}, {"l": "Naloxone", "r": "Competitive antagonist of opioid receptors", "why": "Opioids row."}, {"l": "Digoxin specific antibody fragments", "r": "Binds digoxin, will be renally eliminated", "why": "Digoxin row."}, {"l": "Octreotide", "r": "Inhibits insulin release from the pancreas", "why": "Sulfonylureas and meglitinides row."}], "teach": "The mechanism column for the single-antidote rows: N-acetylcysteine replenishes glutathione; ethanol or fomepizole inhibit alcohol dehydrogenase; flumazenil and naloxone are competitive antagonists at the benzodiazepine and opioid receptors; digoxin antibody fragments bind digoxin for renal elimination; octreotide inhibits insulin release from the pancreas.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Acetaminophen’, ‘Toxic alcohols’, ‘Benzodiazepines’, ‘Opioids’, ‘Digoxin’, ‘Sulfonylureas and miglitinide’"},
{"id": "TBL3-062", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "drug", "concept": "tbl-match-moa-2", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each antidote, in the row named, with its mechanism of action.", "left": ["Deferoxamine (iron)", "Pralidoxime (organophosphates)", "Atropine (organophosphates)", "Sodium bicarbonate (salicylates)", "Sodium bicarbonate (tricyclic antidepressants)", "Glucagon (beta blockers)"], "right": ["Chelates the circulating ferric iron", "Removes organophosphate (OP) from acetylcholinesterase", "Muscarinic acetylcholine receptor antagonist", "Renal ion trapping to enhance elimination", "Counteracts the inhibition on sodium cardiac channels", "Increase cardiac cellular cyclic AMP (cAMP) to increase heart rate"], "pairs": [{"l": "Deferoxamine (iron)", "r": "Chelates the circulating ferric iron", "why": "Iron row."}, {"l": "Pralidoxime (organophosphates)", "r": "Removes organophosphate (OP) from acetylcholinesterase", "why": "Organophosphate row."}, {"l": "Atropine (organophosphates)", "r": "Muscarinic acetylcholine receptor antagonist", "why": "Organophosphate row."}, {"l": "Sodium bicarbonate (salicylates)", "r": "Renal ion trapping to enhance elimination", "why": "Salicylates row."}, {"l": "Sodium bicarbonate (tricyclic antidepressants)", "r": "Counteracts the inhibition on sodium cardiac channels", "why": "Tricyclic antidepressants row."}, {"l": "Glucagon (beta blockers)", "r": "Increase cardiac cellular cyclic AMP (cAMP) to increase heart rate", "why": "Beta blocker row."}], "teach": "The mechanism column for the remaining antidotes. Deferoxamine chelates the circulating ferric iron; pralidoxime removes the organophosphate (OP) from acetylcholinesterase; atropine for organophosphates is a muscarinic acetylcholine receptor antagonist. Sodium bicarbonate has two entries: renal ion trapping for salicylates, and counteracting sodium cardiac channel inhibition for tricyclic antidepressants. Glucagon raises cardiac cAMP to increase heart rate.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Iron’, ‘Organophosphate Insecticides’, ‘Salicylates’, ‘Tricyclic Antidepressants’, ‘Beta blockers’"},
{"id": "TBL3-063", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "recall", "concept": "tbl-match-symptoms-1", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each poisoning with the symptoms listed for it.", "left": ["Acetaminophen", "Benzodiazepines", "Opioids", "Beta blockers", "Calcium channel blockers", "Digoxin"], "right": ["Nausea/vomiting; clinical signs of liver failure", "Central nervous system (CNS) depression and relatively normal vitals", "Somnolence, coma, decreased heart and breath rates, decreased pupils", "Hypotension, bradycardia, altered mental status, respiratory depression", "Hypotension, bradycardia, but often alert", "Bradycardia, arrhythmias, elevated serum potassium, nausea/vomiting"], "pairs": [{"l": "Acetaminophen", "r": "Nausea/vomiting; clinical signs of liver failure", "why": "Acetaminophen row."}, {"l": "Benzodiazepines", "r": "Central nervous system (CNS) depression and relatively normal vitals", "why": "Benzodiazepines row."}, {"l": "Opioids", "r": "Somnolence, coma, decreased heart and breath rates, decreased pupils", "why": "Opioids row."}, {"l": "Beta blockers", "r": "Hypotension, bradycardia, altered mental status, respiratory depression", "why": "Beta blocker row."}, {"l": "Calcium channel blockers", "r": "Hypotension, bradycardia, but often alert", "why": "Calcium channel blocker row."}, {"l": "Digoxin", "r": "Bradycardia, arrhythmias, elevated serum potassium, nausea/vomiting", "why": "Digoxin row."}], "teach": "Six symptom entries to tell apart. Beta blockers and calcium channel blockers share hypotension and bradycardia; altered mental status and respiratory depression mark the beta blocker, and an often-alert patient marks the calcium channel blocker. Opioids lower heart and breathing rates and shrink the pupils; benzodiazepines depress the central nervous system (CNS) with relatively normal vitals. Digoxin adds elevated serum potassium.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Acetaminophen’, ‘Benzodiazepines’, ‘Opioids’, ‘Beta blockers’, ‘Calcium channel blockers’, ‘Digoxin’"},
{"id": "TBL3-064", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "recall", "concept": "tbl-match-symptoms-2", "tags": ["smith", "key"], "source": "slide", "type": "match", "stem": "Match each poisoning with the symptoms listed for it.", "left": ["Methanol", "Ethylene glycol", "Tricyclic antidepressants", "Salicylates", "Sulfonylureas and meglitinides", "Organophosphate insecticides"], "right": ["Anion-gap metabolic acidosis and ocular toxicity", "Metabolites crystallize in the microvasculature; renal toxicity common", "Tachycardia, dilated pupils, dry mouth, agitation, seizures, elongated QRS interval", "Hyperventilation and respiratory alkalosis, then metabolic acidosis", "Hypoglycemia", "Acetylcholine excess: SLUDGE or DUMBELLS"], "pairs": [{"l": "Methanol", "r": "Anion-gap metabolic acidosis and ocular toxicity", "why": "Toxic alcohols row, methanol."}, {"l": "Ethylene glycol", "r": "Metabolites crystallize in the microvasculature; renal toxicity common", "why": "Toxic alcohols row, ethylene glycol."}, {"l": "Tricyclic antidepressants", "r": "Tachycardia, dilated pupils, dry mouth, agitation, seizures, elongated QRS interval", "why": "Tricyclic antidepressants row."}, {"l": "Salicylates", "r": "Hyperventilation and respiratory alkalosis, then metabolic acidosis", "why": "Salicylates row."}, {"l": "Sulfonylureas and meglitinides", "r": "Hypoglycemia", "why": "Sulfonylureas and meglitinides row."}, {"l": "Organophosphate insecticides", "r": "Acetylcholine excess: SLUDGE or DUMBELLS", "why": "Organophosphate row."}], "teach": "The other six symptom entries. Methanol metabolites cause anion-gap metabolic acidosis and ocular toxicity; ethylene glycol metabolites crystallize in small vessels and harm the kidney. Tricyclic antidepressants show tachycardia, dilated pupils and dry mouth with an elongated QRS interval; salicylates move from respiratory alkalosis to metabolic acidosis; sulfonylureas cause hypoglycemia; organophosphates cause acetylcholine excess.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Toxic alcohols’, ‘Tricyclic Antidepressants’, ‘Salicylates’, ‘Sulfonylureas and miglitinide’, ‘Organophosphate Insecticides’"},
{"id": "TBL3-065", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "apply", "concept": "tbl-match-special", "tags": ["smith", "key"], "source": "both", "type": "match", "stem": "Match each special-considerations question with the answer in her key.", "left": ["Acetaminophen: when does the antidote lose effectiveness, and should you still give it?", "Toxic alcohols: is one of the two treatments better, and why?", "Benzodiazepines: concerns with the antidote?", "Beta blockers: what distinguishes the overdose from a calcium channel blocker overdose?", "Digoxin: why are serum levels not helpful after the antidote?", "Opioids: concern in chronic opioid users?"], "right": ["About 8 hours after overdose; yes", "Fomepizole: stronger alcohol dehydrogenase inhibitor, fewer adverse effects", "Withdrawal symptoms in a benzodiazepine-dependent patient", "Altered mental status in beta-blocker overdose", "Total digoxin, free and bound to Fab, is increased", "It can trigger withdrawal"], "pairs": [{"l": "Acetaminophen: when does the antidote lose effectiveness, and should you still give it?", "r": "About 8 hours after overdose; yes", "why": "Acetaminophen row."}, {"l": "Toxic alcohols: is one of the two treatments better, and why?", "r": "Fomepizole: stronger alcohol dehydrogenase inhibitor, fewer adverse effects", "why": "Toxic alcohols row."}, {"l": "Benzodiazepines: concerns with the antidote?", "r": "Withdrawal symptoms in a benzodiazepine-dependent patient", "why": "Benzodiazepines row."}, {"l": "Beta blockers: what distinguishes the overdose from a calcium channel blocker overdose?", "r": "Altered mental status in beta-blocker overdose", "why": "Beta blocker row."}, {"l": "Digoxin: why are serum levels not helpful after the antidote?", "r": "Total digoxin, free and bound to Fab, is increased", "why": "Digoxin row."}, {"l": "Opioids: concern in chronic opioid users?", "r": "It can trigger withdrawal", "why": "Opioids row."}], "teach": "Six rows carry a special-considerations question. The other six (calcium channel blockers, tricyclic antidepressants, salicylates, sulfonylureas and meglitinides, iron, organophosphates) have none; on 10/20 she said a row without a question has nothing really unusual about it.", "quote": "Um, what did you guys think about the column in the table where I, I asked you to answer some questions, I called it special considerations. ... No, if I didn't have a question, there's nothing really weird about that poisoning. I just was pointing out some, some concerns, some issues with some of these exposures that we need to think about.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Acetaminophen’, ‘Toxic alcohols’, ‘Benzodiazepines’, ‘Beta blockers’, ‘Digoxin’, ‘Opioids’; transcript 10/20"},
{"id": "TBL3-066", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "about", "skill": "recall", "concept": "tbl-key-depth", "tags": ["smith", "key"], "source": "both", "stem": "How much detail of the poisoning treatment table is expected on the exam?", "options": [{"t": "The details in her key; what the key has is sufficient", "correct": true, "why": "Her words on 10/20: what is in her table key is sufficient, and the details in the key must be known."}, {"t": "Everything in the DiPiro chapter and the Marraffa article", "correct": false, "why": "She said students often write more than the key, which is fine, but the key is sufficient."}, {"t": "Only the antidote names; mechanisms are not tested", "correct": false, "why": "The key includes mechanisms, and she said its details must be known."}, {"t": "None; the table is a completion grade only", "correct": false, "why": "The table is turned in for a completion grade, but she said the details in the key must be known."}, {"t": "Only the rows she discussed aloud", "correct": false, "why": "She did not walk through the rows; she said the key sets the depth."}], "teach": "On 10/20 she said that students often answer in more detail than her key, which is good for learning, but what is in her key is sufficient, and the details in her key must be known. On 10/19 she said toxicology is tested on the board exam and that the class needs to know this table.", "quote": "So what I have in my table in the key is sufficient. ... But you do know, need to know the details that I have in my table, my key.", "cite": "PoisoningTreatmentTable2026KEY.pdf; transcript 10/20; transcript 10/19 (board exam)"},
{"id": "TBL3-067", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "about", "skill": "recall", "concept": "tbl-special-empty", "tags": ["smith", "key"], "source": "both", "stem": "Several rows of the table have no question in the special-considerations column. What does an empty cell mean?", "options": [{"t": "Nothing is really weird about that poisoning", "correct": true, "why": "Her words on 10/20: if she did not have a question, there is nothing really weird about that poisoning."}, {"t": "The row will not be tested", "correct": false, "why": "She said the details in her key must be known; an empty special column does not remove the row."}, {"t": "The answer was left for the student to look up in the readings", "correct": false, "why": "Her key fills every question she asked; the empty cells had no question."}, {"t": "The poisoning has no antidote", "correct": false, "why": "Every row lists antidotes or treatments."}], "teach": "The special-considerations column holds her questions about concerns and issues with some of the exposures. Where she did not ask a question, there is nothing really unusual about that poisoning. The calcium channel blocker, tricyclic antidepressant, salicylate, sulfonylurea, iron and organophosphate rows have no question.", "quote": "Um, what did you guys think about the column in the table where I, I asked you to answer some questions, I called it special considerations. ... No, if I didn't have a question, there's nothing really weird about that poisoning. I just was pointing out some, some concerns, some issues with some of these exposures that we need to think about.", "cite": "PoisoningTreatmentTable2026KEY.pdf; transcript 10/20"}
);
